package cli

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// endedSessionSweepAge is how long an ENDED-but-uncondensed session must sit
// before the background sweep may condense it. Condensing early would forfeit
// PostCommit's per-commit carry-forward linkage for sessions whose user is
// still about to commit — CondenseAndMarkFullyCondensed deliberately skips
// FilesTouched sessions for exactly that reason. 24h matches
// activeSessionInteractionThreshold: after a day with no commit, the linkage
// is clearly not coming and the session is just O(N) drag on every commit.
const endedSessionSweepAge = 24 * time.Hour

// isSweepableZombie reports whether the state marks this session as safe for
// the background sweep to fix. It deliberately needs no repository access —
// the priciest thing it does is OwnerExited()'s per-non-ended-state process
// probe, which the `entire status` path already pays per state — so the
// session-start hook caller stays cheap. The sweep itself re-validates
// before acting (see runSessionSweep's safety notes).
//
// Condense-only contract: ENDED sessions whose steps turn out to have no
// shadow branch are doctor's discard case, filtered later — this
// predicate only ever nominates sessions, it never acts.
func isSweepableZombie(st *session.State, now time.Time) bool {
	// Imported sessions are historical records: complete by design, never
	// condensable (no BaseCommit), and exempt from the stale purge — so they
	// may look like zombies forever. Nominating one would spawn a doomed sweep
	// on every session start, forever.
	if st.Kind.IsImported() {
		return false
	}
	if !st.IsEnded() {
		return st.OwnerExited()
	}
	if st.Phase != session.PhaseEnded || st.FullyCondensed || st.StepCount <= 0 {
		return false
	}
	ref := st.EndedAt
	if ref == nil {
		ref = st.LastInteractionTime
	}
	if ref == nil {
		return false // legacy state without timestamps: leave it to doctor
	}
	return now.Sub(*ref) >= endedSessionSweepAge
}

// runSessionSweep is the detached background pass that fixes zombie sessions:
// Non-ended sessions whose owning agent process is gone are finalized exactly
// as a clean SessionStop would (finalizeExitedSessions, which re-validates
// OwnerExited under the per-session lock), and ENDED sessions past the
// carry-forward window with condensable data are condensed via the same
// engine `entire doctor --force` uses.
//
// Safety contract: condense-only, enforced by OUR pre-checks, not by the
// engine.
// CondenseSessionByID's locked closure re-checks only shadow-branch
// existence; we therefore re-load each candidate and re-run the full zombie
// predicate immediately before condensing. That narrows — does not close —
// the window in which a resumed (ENDED→ACTIVE) session gets condensed
// anyway: acceptable, because the precondition is >24h idle (a seconds-wide
// race against a day-old zombie) and a condense of a just-resumed session is
// coherent. The cost of losing that race: the resumed turn's phase is reset to
// IDLE and its pending prompt attribution is lost — recoverable, and
// acceptable at a seconds-vs-24h race. If the shadow branch vanishes between
// our check and the engine's lock, the engine clears the state — correct
// cleanup, since in practice that typically happens when a concurrent condense
// already succeeded; an out-of-band branch deletion (git branch -D,
// entire clean) in the window also lands here. The reverse
// direction is also safe: an ACTIVE session with a dead owner that is being
// resumed right now can be finalized by the sweep mid-resume, because
// finalizeExitedSessions re-validates under the per-session lock and the
// resume's first TurnStart re-establishes state — owner capture happens at
// TurnStart, not SessionStart. Everything is best-effort: a failed session is
// logged and retried by the next sweep.
func runSessionSweep(ctx context.Context) error {
	logCtx := logging.WithComponent(ctx, "session-sweep")

	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		return fmt.Errorf("failed to list session states: %w", err)
	}

	// Non-ended sessions with a dead owner: finalize + eager condense. This
	// command is detached, so a zero deadline lets the backlog drain in one pass
	// instead of inheriting the interactive status/doctor budget. This also
	// refreshes the matched entries in `states` from disk.
	if n := finalizeExitedSessions(ctx, states, time.Time{}); n > 0 {
		logging.Info(logCtx, "sweep finalized exited sessions", slog.Int("count", n))
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return err
	}
	defer repo.Close()

	store, err := session.NewStateStore(ctx)
	if err != nil {
		return fmt.Errorf("failed to open session state store: %w", err)
	}

	now := time.Now()
	for _, st := range states {
		// ENDED-only here: non-ended zombies were finalizeExitedSessions' job
		// above. isSweepableZombie returns true for a non-ended dead-owner
		// session (its finalize failed above), so this phase check is what
		// keeps those out of the condense path — and skips their pointless
		// re-load.
		if st.Phase != session.PhaseEnded || !isSweepableZombie(st, now) {
			continue
		}
		// Re-load and re-check right before acting: the snapshot may be stale
		// (a resumed session flips ENDED→ACTIVE; a concurrent sweep may have
		// condensed it). See the safety contract above for the residual race.
		fresh, lerr := store.Load(ctx, st.SessionID)
		if lerr != nil {
			logging.Debug(logCtx, "sweep re-load failed",
				slog.String("session_id", st.SessionID),
				slog.String("error", lerr.Error()))
			continue
		}
		if fresh == nil {
			continue // benign: state removed/cleaned up between list and load
		}
		if fresh.Phase != session.PhaseEnded || !isSweepableZombie(fresh, now) {
			continue
		}
		if !strategy.IsCondensableEndedSession(repo, fresh) {
			// Uncondensed steps but no shadow branch: fixing this means
			// discarding state, which the sweep never initiates — it is
			// doctor's discard case.
			logging.Info(logCtx, "sweep skipping non-condensable ended session: uncondensed steps but no shadow branch — run `entire doctor` to resolve",
				slog.String("session_id", fresh.SessionID))
			continue
		}
		if condErr := GetStrategy(ctx).CondenseSessionByID(ctx, fresh.SessionID); condErr != nil {
			logging.Warn(logCtx, "sweep condense failed",
				slog.String("session_id", fresh.SessionID),
				slog.String("error", condErr.Error()))
			continue
		}
		logging.Info(logCtx, "sweep condensed ended zombie session",
			slog.String("session_id", fresh.SessionID))
	}
	return nil
}

// countSweepableZombies counts the sessions in states that nominate a
// background sweep. Pure so the spawn decision is unit-testable.
func countSweepableZombies(states []*session.State, now time.Time) int {
	n := 0
	for _, st := range states {
		if isSweepableZombie(st, now) {
			n++
		}
	}
	return n
}

// sweepSpawn is the process-spawn seam used by maybeSpawnSessionSweep.
// Swapped in tests so they can assert the spawn decision (including the
// throttle) without forking a real subprocess (a real `go test` binary doesn't
// understand `__sweep_sessions` as an argument). Production code always uses
// spawnDetachedSessionSweepProcess.
var sweepSpawn = spawnDetachedSessionSweepProcess

// sweepGitCommonDir is the repository-scope seam used by
// maybeSpawnSessionSweep. Swapped in tests to prove a throttle-key failure
// fails closed without depending on a malformed repository fixture.
var sweepGitCommonDir = session.GetGitCommonDir

// spawnDetachedSessionSweepProcess starts `entire __sweep_sessions` as a
// detached child so the sweep's repo work can't add latency to the
// session-start hook that spawned it. The child runs from the worktree root
// because the sweep resolves the repo and session-state directory from its
// working directory.
func spawnDetachedSessionSweepProcess(worktreeRoot string) {
	execx.SpawnDetached(worktreeRoot, "__sweep_sessions")
}

// sessionSweepSpawnThrottle bounds how often the session-start hook forks a
// detached sweep child for a given repo. A zombie that persistently fails to
// condense re-nominates a spawn on every session start; without this guard a
// burst of hooks (or an agent that restarts sessions rapidly) would fork one
// child per hook, each re-opening the repo just to fail the same way. 15
// minutes comfortably covers a burst and a slow in-flight sweep while still
// retrying a transient failure within the same working session.
const sessionSweepSpawnThrottle = 15 * time.Minute

// sweepRecentlySpawned reports whether a detached sweep was spawned for this
// repo within sessionSweepSpawnThrottle and, when it wasn't, records now as
// the most recent spawn. Same flock-serialized marker mechanism as the
// trail-enablement refresh (see recentlySpawnedMarker), with its own marker.
func sweepRecentlySpawned(commonDir string, now time.Time) bool {
	return recentlySpawnedMarker(commonDir, "session-sweep-spawn", sessionSweepSpawnThrottle, now)
}

// maybeSpawnSessionSweep fires one detached __sweep_sessions child when the
// session-state files nominate a zombie. Called from the session-start hook:
// listing the state files is a small shared-directory read, and the sweep
// itself runs detached, so the hook's latency budget is untouched. Best-effort
// throughout — a failure here must never fail the hook.
//
// Spawns are throttled through a flock-serialized marker in the shared
// git-common-dir (sweepRecentlySpawned), so a burst of concurrent or rapid
// session starts collapses to one child per sessionSweepSpawnThrottle window.
// Redundant sweeps re-check under the per-session lock and no-op once one has
// succeeded; a zombie that persistently fails to condense is retried — and
// fails — once per throttle window, which we accept.
func maybeSpawnSessionSweep(ctx context.Context) {
	logCtx := logging.WithComponent(ctx, "session-sweep")
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Debug(logCtx, "skipping sweep spawn: could not resolve worktree root",
			slog.String("error", err.Error()))
		return
	}
	commonDir, err := sweepGitCommonDir(ctx)
	if err != nil {
		logging.Debug(logCtx, "skipping sweep spawn: could not resolve git common dir",
			slog.String("error", err.Error()))
		return
	}
	// Zombie discovery deliberately precedes the throttle check. The shared
	// marker is check-and-record, so consulting it before discovery would burn
	// the whole throttle window on the overwhelmingly common no-zombie case. A
	// read-only marker check would permit reordering if this scan becomes a
	// measurable hook-latency cost.
	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		logging.Warn(logCtx, "skipping sweep check", slog.String("error", err.Error()))
		return
	}
	n := countSweepableZombies(states, time.Now())
	if n == 0 {
		return
	}
	if sweepRecentlySpawned(commonDir, time.Now()) {
		return
	}
	sweepSpawn(root)
	logging.Info(logCtx, "zombie sessions detected, spawned detached sweep",
		slog.Int("count", n))
}
// Package proclive captures a process's identity (PID plus a start-time
// fingerprint) and later reports whether that exact process is still alive.
//
// It exists to detect agent sessions left in an ACTIVE state when the owning
// process went away — a clean exit, a crash, a kill, a closed terminal, or a
// reboot — without firing a SessionStop hook. Recording the owner's identity at
// turn start lets `entire status` / `entire doctor` notice the process is gone
// immediately, instead of waiting out a coarse inactivity timeout.
//
// This package is a leaf: it imports only the standard library and
// golang.org/x/sys/unix. It must NOT import session, strategy, agent, or cli,
// so those packages can depend on it without an import cycle.
package proclive

import (
	"errors"
	"os"
	"strings"
)

// Liveness is the result of checking a recorded process Identity.
type Liveness int

const (
	// LivenessUnknown means liveness could not be determined: the identity is
	// empty, was recorded on another host, or the platform cannot introspect
	// processes. Callers should fall back to a time-based heuristic.
	LivenessUnknown Liveness = iota
	// LivenessAlive means the recorded process is still running.
	LivenessAlive
	// LivenessDead means the recorded process is gone (exited, killed, or the
	// machine rebooted) or its PID has been reused by a different process.
	LivenessDead
)

func (l Liveness) String() string {
	switch l {
	case LivenessAlive:
		return "alive"
	case LivenessDead:
		return "dead"
	case LivenessUnknown:
		return "unknown"
	default:
		return "unknown"
	}
}

// Identity fingerprints the process that owns a session turn. It is persisted
// in session state and later passed to Check. The zero value means "no owner
// recorded" and always yields LivenessUnknown.
type Identity struct {
	// PID is the operating-system process id of the owner.
	PID int `json:"pid"`
	// Start is an opaque, per-platform process start-time fingerprint. It need
	// only be stable for the process lifetime and distinct across PID reuse
	// within a single boot; the Boot guard invalidates it across reboots.
	Start string `json:"start"`
	// Boot identifies the current OS boot. A mismatch at check time means the
	// machine rebooted, so the recorded PID cannot still be the same process.
	Boot string `json:"boot,omitempty"`
	// Host is the hostname where the identity was recorded. PIDs are only
	// meaningful on their own machine, so a mismatch yields Unknown.
	Host string `json:"host,omitempty"`
	// Name is the owning process's executable name (comm). Diagnostic only.
	Name string `json:"name,omitempty"`
}

var (
	// errProcessGone is returned by procStat when no process with the given PID
	// exists. Check maps it to LivenessDead.
	errProcessGone = errors.New("proclive: process not found")
	// errUnsupported is returned by the per-platform seam when the OS cannot be
	// introspected (e.g. Windows). Check maps it to LivenessUnknown.
	errUnsupported = errors.New("proclive: unsupported platform")
)

// maxAncestorDepth bounds the ResolveOwner walk so a pathological or cyclic
// process tree can never loop or hang.
const maxAncestorDepth = 12

// transientNames are process names that are never the long-lived session owner:
// our own hook binary, the shells agents commonly use to exec hooks, and the Go
// toolchain (a `go run`-launched hook has a short-lived `go` parent that would
// otherwise be recorded as the owner and exit immediately). The walk skips
// past these to reach the real agent process. Note that interpreter runtimes
// (node, bun, python) are deliberately absent — for several agents the runtime
// IS the long-lived agent, so treating it as transient would skip the real owner.
var transientNames = map[string]bool{
	"entire": true,
	"sh":     true,
	"bash":   true,
	"zsh":    true,
	"dash":   true,
	"fish":   true,
	"ash":    true,
	"ksh":    true,
	"env":    true,
	"go":     true,
}

func isTransient(name string) bool {
	return transientNames[strings.ToLower(strings.TrimSpace(name))]
}

// ResolveOwner walks up the process tree from the current process and returns
// the Identity of the first ancestor that is not our own hook binary or a
// shell — i.e. the long-lived agent that owns this session.
//
// It returns (zero, false) when no such ancestor can be determined: an
// unsupported platform, a truncated/looping tree, or only transient ancestors.
// In that case the caller should record no owner and let liveness degrade to
// the time-based fallback. Resolving to nothing is always safer than recording
// a guessed PID, which could later be (mis)read as a live or dead owner.
func ResolveOwner() (Identity, bool) {
	// The host guard is essential — a PID is only meaningful on the machine that
	// recorded it — so if the hostname can't be determined, record no owner
	// rather than an unguarded one that Check could later (mis)classify as
	// alive/dead across machines. Boot is a best-effort secondary guard; an
	// empty value just disables it (darwin records none — see bootID there).
	host, err := os.Hostname()
	if err != nil || host == "" {
		return Identity{}, false
	}
	boot, err := bootID()
	if err != nil {
		boot = ""
	}

	// Walk up from our own process, reading each ancestor exactly once: procStat
	// returns its parent (to continue the walk), its name (to skip shells and our
	// own binary), and its start fingerprint (to record).
	candidate, _, _, err := procStat(os.Getpid())
	if err != nil {
		return Identity{}, false
	}
	for range maxAncestorDepth {
		if candidate <= 1 {
			return Identity{}, false
		}
		parent, name, start, err := procStat(candidate)
		if err != nil {
			return Identity{}, false
		}
		if !isTransient(name) {
			return Identity{PID: candidate, Start: start, Boot: boot, Host: host, Name: name}, true
		}
		candidate = parent
	}
	return Identity{}, false
}

// Check reports whether the process recorded in id is still alive.
//
// Precedence: an empty identity or a host mismatch is Unknown (cannot judge); a
// boot mismatch means a reboot, so the process is Dead; a missing PID or a
// start-fingerprint mismatch (PID reuse) is Dead; otherwise Alive. An
// unsupported platform is always Unknown so callers fall back to a timeout.
func Check(id Identity) Liveness {
	if id.PID <= 0 {
		return LivenessUnknown
	}
	if id.Host != "" {
		// Can't confirm we're on the recording host → can't trust its PIDs.
		host, err := os.Hostname()
		if err != nil || host != id.Host {
			return LivenessUnknown
		}
	}
	if id.Boot != "" {
		boot, err := bootID()
		switch {
		case err != nil || boot == "":
			return LivenessUnknown // can't confirm the boot → can't trust the PID
		case boot != id.Boot:
			return LivenessDead // rebooted: the process cannot have survived
		}
	}

	_, _, start, err := procStat(id.PID)
	switch {
	case errors.Is(err, errUnsupported):
		return LivenessUnknown
	case errors.Is(err, errProcessGone):
		return LivenessDead
	case err != nil:
		// Transient/unexpected error: don't claim the process is dead.
		return LivenessUnknown
	}
	if id.Start != "" && start != "" && id.Start != start {
		// Same PID, different start time: the PID was reused by another process.
		return LivenessDead
	}
	return LivenessAlive
}
// It is a no-op when HEAD is detached or cannot be read — the branch field is
// best-effort and resume derives it from commit trailers when absent.
func captureSessionBranch(repo *git.Repository, state *SessionState) {
	headRef, err := repo.Head()
	if err != nil {
		return
	}
	if headRef.Name().IsBranch() {
		state.Branch = headRef.Name().Short()
	} else {
		// Detached HEAD: clear any branch recorded on a previous turn so resume
		// falls back to deriving the branch from checkpoint trailers instead of
		// using a stale, now-incorrect value.
		state.Branch = ""
	}
}

// captureSessionOwner records the owning agent process (PID + start-time
// fingerprint) into the session state so liveness checks can later detect an
// ACTIVE session whose agent exited without firing a SessionStop hook. The hook
// runs as a short-lived child of the agent, so proclive.ResolveOwner walks up
// past our own binary and any shells to the long-lived agent process.
//
// It is best-effort and re-run on every turn start: if the owner can't be
// resolved (unsupported platform, transient-only ancestry) the field is cleared
// and liveness degrades to the inactivity timeout; re-resolving each turn keeps
// the fingerprint current across agent restarts.
func captureSessionOwner(state *SessionState) {
	// Clear first: a failed resolve must never leave a stale owner from an
	// earlier turn. Otherwise a now-live session (agent restarted with a new
	// PID) could still carry a dead PID and be wrongly finalized as exited.
	state.Owner = nil
	if owner, ok := proclive.ResolveOwner(); ok {
		state.Owner = &owner
	}
}

// calculatePromptAttributionAtStart calculates attribution at prompt start (before agent runs).
// This captures user changes since the last checkpoint - no filtering needed since
// the agent hasn't made any changes yet.
//
// IMPORTANT: This reads from the worktree (not staging area) to match what WriteTemporary
// captures in checkpoints. If we read staged content but checkpoints capture worktree content,
// unstaged changes would be in the checkpoint but not counted in PromptAttribution, causing
// them to be incorrectly attributed to the agent later.
func (s *ManualCommitStrategy) calculatePromptAttributionAtStart(
	ctx context.Context,
	repo *git.Repository,
	state *SessionState,
) PromptAttribution {
	logCtx := logging.WithComponent(ctx, "attribution")
	nextCheckpointNum := state.StepCount + 1
	result := PromptAttribution{CheckpointNumber: nextCheckpointNum}

	// Get last checkpoint tree from shadow branch (if it exists).
	// For a new session (StepCount == 0), always use baseTree as the reference.
	// The shadow branch may contain checkpoints from OTHER concurrent sessions,
	// and using that tree would miss pre-session worktree dirt (e.g., .claude/settings.json)
	// because it appears unchanged when compared to another session's snapshot.
	var lastCheckpointTree *object.Tree
	if state.StepCount > 0 {
		// Existing session with prior checkpoints — use shadow branch as reference.
		shadowBranchName := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
		refName := plumbing.NewBranchReferenceName(shadowBranchName)
		if ref, err := repo.Reference(refName, true); err != nil {
			logging.Debug(logCtx, "prompt attribution: no shadow branch",
				slog.String("shadow_branch", shadowBranchName))
		} else if shadowCommit, err := repo.CommitObject(ref.Hash()); err != nil {
			logging.Debug(logCtx, "prompt attribution: failed to get shadow commit",
				slog.String("shadow_ref", ref.Hash().String()),
				slog.String("error", err.Error()))
		} else if tree, err := shadowCommit.Tree(); err != nil {
			logging.Debug(logCtx, "prompt attribution: failed to get shadow tree",
				slog.String("error", err.Error()))
		} else {
			lastCheckpointTree = tree
		}
	}
	// For new sessions (StepCount == 0), lastCheckpointTree stays nil.
	// CalculatePromptAttribution falls back to baseTree, ensuring pre-session
	// worktree dirt is captured even when the shadow branch has other sessions' data.

	// Get base tree for agent lines calculation
	var baseTree *object.Tree
	if baseCommit, err := repo.CommitObject(plumbing.NewHash(state.BaseCommit)); err == nil {
		if tree, treeErr := baseCommit.Tree(); treeErr == nil {
			baseTree = tree
		} else {
			logging.Debug(logCtx, "prompt attribution: base tree unavailable",
				slog.String("error", treeErr.Error()))
		}
	} else {
		logging.Debug(logCtx, "prompt attribution: base commit unavailable",
			slog.String("base_commit", state.BaseCommit),
			slog.String("error", err.Error()))
	}

	worktree, err := repo.Worktree()
	if err != nil {
		logging.Debug(logCtx, "prompt attribution skipped: failed to get worktree",
			slog.String("error", err.Error()))
		// and (by design) no BaseCommit. Keep them regardless of the
		// shadow-branch orphan check below. Gate on Kind, not on commit
		// presence, so this stays correct once imports are linked to a commit.
		if state.Kind.IsImported() {
			states = append(states, state)
			continue
		}

		// Skip and cleanup orphaned sessions whose shadow branch no longer exists.
		// Keep active sessions (shadow branch may not be created yet) and sessions
		// with LastCheckpointID (needed for checkpoint ID reuse on subsequent commits).
		// Clean up everything else: stale pre-state-machine sessions (empty phase),
		// IDLE/ENDED sessions that were never condensed, etc.
		// Record-bearing sessions hold condensable content off the shadow branch — never orphaned.
		shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
		refName := plumbing.NewBranchReferenceName(shadowBranch)
		if _, err := repo.Reference(refName, true); err != nil {
			if !state.Phase.IsActive() && state.LastCheckpointID.IsEmpty() && !state.HasTaskContent() {
				//nolint:errcheck,gosec // G104: Cleanup is best-effort, shouldn't fail the list operation
				store.Clear(ctx, state.SessionID)
				continue
			}
		}

		states = append(states, state)
	}
	return states, nil
}

// IsCondensableEndedSession reports whether an ENDED session still carries
// uncondensed content AND can be salvaged by condensing
// (CondenseSessionByID). Two shapes qualify: checkpoint steps whose shadow
// branch still exists, and record-bearing sessions (pending subagent task
// records), whose content never lives on the shadow branch and so needs no
// branch to condense. ENDED sessions with steps but no shadow branch and no
// task records are NOT condensable; fixing those means discarding state,
// which the background sweep never initiates — those sessions are left to
// `entire doctor` (and the existing orphan cleanup in listAllSessionStates).
// Used by the PostCommit stale-session warning and the background zombie
// sweep.
func IsCondensableEndedSession(repo *git.Repository, state *SessionState) bool {
	if state.Phase != session.PhaseEnded || state.FullyCondensed ||
		(state.StepCount <= 0 && !state.HasTaskContent()) {
		return false
	}

	// Record-bearing sessions qualify without a shadow branch: task records
	// are stored off-branch, so condensation can materialize them regardless.
	if state.HasTaskContent() {
		return true
	}

	// Check shadow branch existence. For PostCommit this is a re-check —
	// its list arrives via listAllSessionStates, which already filters
	// orphaned sessions — and it is intentional even there: condensation
	// deletes shadow branches, so a branch that existed at list-load time may
	// be gone by the time the warning re-checks here, and we'd otherwise warn
	// about a session this commit (or a concurrent condense) just cleaned up.
	// The background zombie sweep, by contrast, arrives via the raw
	// ListSessionStates, so for the sweep this is the PRIMARY shadow-branch
	// check, not a re-check — it is what keeps the sweep condense-only.
	shadowBranch := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	refName := plumbing.NewBranchReferenceName(shadowBranch)
	_, err := repo.Reference(refName, true)
	return err == nil
}

// countWarnableStaleEndedSessions returns the number of ENDED sessions that
// still remain slow and fixable after PostCommit finishes processing.
func countWarnableStaleEndedSessions(repo *git.Repository, sessions []*SessionState) int {
	n := 0
	for _, state := range sessions {
		if IsCondensableEndedSession(repo, state) {
			n++
		}
	}
	return n
}

// findExactSessionsForWorktree returns sessions recorded for exactly this
// worktree path, with no sibling/parent fallback. Callers that mutate
// worktree-coupled state (e.g. BaseCommit, which must only follow the HEAD of
// the session's own worktree) must use this instead of
// findSessionsForWorktree.
func (s *ManualCommitStrategy) findExactSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
	allStates, err := s.listAllSessionStates(ctx)
	if err != nil {
		return nil, err
	}
	return exactWorktreeMatches(allStates, worktreePath), nil
}

func exactWorktreeMatches(states []*SessionState, worktreePath string) []*SessionState {
	var exact []*SessionState
	for _, state := range states {
		if state.WorktreePath == worktreePath {
			exact = append(exact, state)
		}
	}
	return exact
}

// findSessionsForWorktree finds all sessions for the given worktree path.
// Exact WorktreePath matches win; otherwise sessions recorded in another
// worktree of the same repository (shared git common dir) are matched, as long
// as all candidates come from a single worktree.
func (s *ManualCommitStrategy) findSessionsForWorktree(ctx context.Context, worktreePath string) ([]*SessionState, error) {
	allStates, err := s.listAllSessionStates(ctx)
	if err != nil {
		return nil, err
	}

	if exact := exactWorktreeMatches(allStates, worktreePath); len(exact) > 0 {
		return exact, nil
	}

	worktreeCommonDir, err := gitCommonDirForWorktree(ctx, worktreePath)
	if err != nil {
		return nil, fmt.Errorf("resolve common dir for fallback session matching: %w", err)
	}

	var parentWorktreeMatches []*SessionState
	var commonDirMatches []*SessionState
	commonDirByPath := make(map[string]string)
	for _, state := range allStates {
		if state.WorktreePath == "" {
			continue
		}

		stateCommonDir, seen := commonDirByPath[state.WorktreePath]
		if !seen {
			stateCommonDir = gitCommonDirForWorktreeOrEmpty(ctx, state.WorktreePath)
			commonDirByPath[state.WorktreePath] = stateCommonDir
		}
		if stateCommonDir == "" || stateCommonDir != worktreeCommonDir {
			continue
		}

		if isNestedWorktreeOfRecordedRepo(state.WorktreePath, worktreePath) {
			parentWorktreeMatches = append(parentWorktreeMatches, state)
			continue
		}

		commonDirMatches = append(commonDirMatches, state)
	}

	if len(parentWorktreeMatches) > 0 {
		matches := sessionsFromSingleWorktree(parentWorktreeMatches)
		if matches == nil {
			warnAmbiguousWorktreeSessions(ctx, worktreePath, parentWorktreeMatches)
		}
		return matches, nil
	}
	matches := sessionsFromSingleWorktree(commonDirMatches)
	if matches == nil && len(commonDirMatches) > 0 {
		warnAmbiguousWorktreeSessions(ctx, worktreePath, commonDirMatches)
	}
	return matches, nil
}

// warnAmbiguousWorktreeSessions surfaces refused fallback matches: live
// sessions exist in other worktrees of this repo, but they span multiple
// worktrees so no automatic match is safe. Without this warning, commits made
// here silently lose their Entire-Checkpoint linkage (#1852) with only a
// DEBUG-level trace.
func warnAmbiguousWorktreeSessions(ctx context.Context, worktreePath string, candidates []*SessionState) {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	seen := make(map[string]struct{}, len(candidates))
	worktrees := make([]string, 0, len(candidates))
	for _, state := range candidates {
		if _, ok := seen[state.WorktreePath]; ok {
			continue
		}
		seen[state.WorktreePath] = struct{}{}
		worktrees = append(worktrees, state.WorktreePath)
	}
	logging.Warn(logCtx, "session matching: ambiguous sessions across worktrees; commit will not be linked",
		slog.String("commit_worktree", worktreePath),
		slog.Int("candidate_sessions", len(candidates)),
		slog.Any("candidate_worktrees", worktrees),
	)
}

// sessionsFromSingleWorktree returns the candidates only when they were all
// recorded in the same worktree. Multiple sessions in one worktree is the
// supported concurrent-session case (matching exact-match semantics);
// candidates spanning distinct worktrees are ambiguous, so no fallback match
// is made rather than guessing which worktree the commit belongs to.
func sessionsFromSingleWorktree(candidates []*SessionState) []*SessionState {
	if len(candidates) == 0 {
		return nil
	}
	first := candidates[0].WorktreePath
	for _, state := range candidates[1:] {
		if state.WorktreePath != first {
			return nil
		}
	}
	return candidates
}

// reconcileWorktreePathForResumedTurn repoints a main-worktree session's recorded
// WorktreePath when a turn starts from a different main worktree AND the recorded
// path no longer resolves to this repository's git common dir. That is the
// repo-relocation case (#1890): the whole repo directory was renamed or moved
// while the session was stopped, then the agent resumed the same session from the
// new location. WorktreePath is matched by exact string equality at commit time
// (findSessionsForWorktree), so without this the resumed session's commits
// silently lose their Entire-Checkpoint trailer.
//
// Scope is deliberately restricted to relocations between MAIN worktrees
// (WorktreeID == "" on both the recorded state and the current worktree). Doing
// so keeps WorktreePath and WorktreeID aligned by construction: both stay "".
// Repointing a linked-worktree session (WorktreeID != "") onto the main worktree
// would leave WorktreeID describing a different worktree than WorktreePath, and
// that disalignment breaks every consumer that re-derives the worktree id from
// the current directory — `entire clean` and `entire explain` compute the wrong
// shadow-branch name (orphaning or hiding the session's checkpoints), and the
// post-commit base/attribution updates follow the wrong worktree's HEAD.
// Linked-worktree relocation is a rare, documented non-goal; the zero-match path
// still warns so the trailer loss is not silent.
	// PromptWindowResetPending indicates a checkpoint was just written and the
	// window base must be re-anchored to the current SessionTurnCount the next time
	// a turn is counted. Deferred so back-to-back checkpoints share a count.
	PromptWindowResetPending bool `json:"prompt_window_reset_pending,omitempty"`

	// Deprecated: TranscriptLinesAtStart is replaced by CheckpointTranscriptStart.
	// Kept for backward compatibility with existing state files.
	TranscriptLinesAtStart int `json:"transcript_lines_at_start,omitempty"`

	// TranscriptIdentifierAtStart is the last transcript identifier when the session started.
	// Used for identifier-based transcript scoping (UUID for Claude, message ID for Gemini).
	TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"`

	// TranscriptPath is the path to the live transcript file (for mid-session commit detection)
	TranscriptPath string `json:"transcript_path,omitempty"`

	// LastPrompt is the most recent user prompt for this session (truncated for display).
	// Updated on every turn start (UserPromptSubmit). JSON tag kept as "first_prompt"
	// for backward compatibility with existing state files.
	LastPrompt string `json:"last_prompt,omitempty"`

	// PromptAttributions tracks user and agent line changes at each prompt start.
	// This enables accurate attribution by capturing user edits between checkpoints.
	PromptAttributions []PromptAttribution `json:"prompt_attributions,omitempty"`

	// PendingPromptAttribution holds attribution calculated at prompt start (before agent runs).
	// This is moved to PromptAttributions when SaveStep is called.
	PendingPromptAttribution *PromptAttribution `json:"pending_prompt_attribution,omitempty"`

	// Owner fingerprints the process that owns this session's agent turn,
	// captured at each turn start via proclive.ResolveOwner. It lets liveness
	// checks detect an ACTIVE session whose agent has exited (clean /exit,
	// crash, kill, terminal close, reboot) without a SessionStop hook firing —
	// see OwnerExited. nil for legacy sessions or when the owner couldn't be
	// resolved, in which case liveness falls back to the StuckActiveThreshold
	// timeout. Only meaningful on Owner.Host.
	Owner *proclive.Identity `json:"owner,omitempty"`

	// TaskRecords tracks subagents dispatched by this session — the durable
	// pointer ledger for subagent work. See TaskRecord.
	TaskRecords []TaskRecord `json:"task_records,omitempty"`
}

// TaskRecord is the durable pointer ledger entry for a subagent dispatched by
// this session: a small session-state record (correlation ID, agent type,
// description, declared transcript path, files touched, tokens) rather than a
// shadow-tree write. Condensation is what materializes a record's transcript
// (sanitize → externalize → redact) into the parent session's checkpoint —
// see docs/superpowers/plans/2026-08-19-subagent-durable-records.md.
//
// CompletedAt zero means the record is still in flight (background launch
// observed, no completion signal yet); non-zero means the record was
// completed — via CompleteTaskRecord — by a foreground/background post-task
// capture, SubagentStop, or the SessionEnd sweep. Unlike the prior
// remove-on-claim model, a completed record is NOT deleted: it must persist
// so a later condensation can materialize its transcript. Consumed by the
// Final captures — the SubagentStop handler (handleSubagentStopFinal) and the
// SessionEnd sweep (completeLiveTaskRecords). A Final capture completes the
// record LAST, after successful extraction (strategy.CompleteTaskRecord's
// exactly-once mutation), so a failed capture leaves the record live for the
// SessionEnd sweep to retry.
type TaskRecord struct {
	// ToolUseID is the Task tool invocation's tool_use_id — the same ID used
	// to key TaskMetadataDir. Dedup key for AddTaskRecord.
	ToolUseID string `json:"tool_use_id"`

	// AgentID is the subagent identifier (tool_response.agentId at launch
	// time), used to resolve the subagent's own transcript file.
	AgentID string `json:"agent_id,omitempty"`

	// StartedAt is when the background launch was observed.
	StartedAt time.Time `json:"started_at"`

	// SubagentType and TaskDescription are captured at launch time because
	// SubagentStop payloads carry no tool_input — a Final-path capture has no
	// way to derive them from the event itself (ParseSubagentTypeAndDescription
	// yields empty strings on a nil ToolInput). The Final handler reads these
	// from the record to label the task step, falling back to the event's own
	// fields only when the record is absent.
	SubagentType    string `json:"subagent_type,omitempty"`
	TaskDescription string `json:"task_description,omitempty"`

	// DeclaredTranscriptPath is the subagent transcript path an agent's stop
	// hook declared (e.g. Claude Code's agent_transcript_path, or the
	// equivalent Codex/Cursor field) — the path #2058 says must not be lost
	// between mid-turn capture and condensation-time materialization. Empty
	// when no declared path was available; the materializer falls back to
	// ResolveAgentTranscriptPath in that case.
	DeclaredTranscriptPath string `json:"declared_transcript_path,omitempty"`

	// Files is the set of files touched by this subagent, merged into the
	// session's FilesTouched at completion time. Populated when the record
	// is completed; empty for a still in-flight record and for a completed
	// read-only subagent.
	Files []string `json:"files,omitempty"`

	// TokenUsage is this subagent's token usage, when the completing hook
	// payload provided one. nil when unavailable.
	TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`

	// CompletedAt is when this record was completed (CompleteTaskRecord).
	// Zero means the record is still in flight. See the type doc comment.
	CompletedAt time.Time `json:"completed_at,omitempty"`
}

// AddTaskRecord records a subagent launch, replacing any existing entry with
// the same ToolUseID. Dedup by ToolUseID: a retried or duplicate launch event
// must not create two records for the same task, which would make
// RemoveTaskRecord leave a stale entry behind after the first is cleared.
func (s *State) AddTaskRecord(task TaskRecord) {
	for i, existing := range s.TaskRecords {
		if existing.ToolUseID == task.ToolUseID {
			s.TaskRecords[i] = task
			return
		}
	}
	s.TaskRecords = append(s.TaskRecords, task)
}

// RemoveTaskRecord clears the record for toolUseID, if present. No-op when no
// record matches. Retained for tests and any caller that genuinely wants to
// discard a record outright — ordinary completion should use
// CompleteTaskRecord instead, which keeps the record for the materializer.
func (s *State) RemoveTaskRecord(toolUseID string) {
	for i, existing := range s.TaskRecords {
		if existing.ToolUseID == toolUseID {
			s.TaskRecords = append(s.TaskRecords[:i], s.TaskRecords[i+1:]...)
			return
		}
	}
}

// FindTaskRecord returns a pointer to the record for toolUseID, or nil if
// none exists. The pointer aliases the slice element, so callers must not
// retain it across a mutation that could reallocate TaskRecords (e.g.
// AddTaskRecord, RemoveTaskRecord).
func (s *State) FindTaskRecord(toolUseID string) *TaskRecord {
	for i := range s.TaskRecords {
		if s.TaskRecords[i].ToolUseID == toolUseID {
			return &s.TaskRecords[i]
		}
	}
	return nil
}

// CompleteTaskRecord marks the record for toolUseID as consumed exactly
// once: it sets CompletedAt and returns true, or returns false — a no-op —
// when no record exists for toolUseID or it was already completed
// (CompletedAt already non-zero). This is the exactly-once completion guard
// equivalent to the old claim-and-remove semantics: whichever caller
// observes true proceeds with the capture, a racing duplicate sees false and
// skips.
//
// The data fields (DeclaredTranscriptPath, Files, TokenUsage) are NOT set
// here. They are populated separately by the producer after successful
// extraction, via direct field mutation on the claimed record within the
// same MutateSessionState closure that called CompleteTaskRecord — see
// strategy.CompleteTaskRecord, the producer-facing wrapper that pairs the
// claim with the attach inside one lock.
func (s *State) CompleteTaskRecord(toolUseID string, completedAt time.Time) bool {
	for i := range s.TaskRecords {
		if s.TaskRecords[i].ToolUseID != toolUseID {
			continue
		}
		if !s.TaskRecords[i].CompletedAt.IsZero() {
			return false
		}
		s.TaskRecords[i].CompletedAt = completedAt
		return true
	}
	return false
}

// HasTaskContent reports whether this session carries pending subagent task
// content: any task record — live (transcript-so-far still needs capturing)
// or completed-unmaterialized (awaiting condensation) — counts. Condensation
// triggers and session-empty guards key on this, not on shadow-branch
// existence: task records never touch the shadow branch.
func (s *State) HasTaskContent() bool {
	return len(s.TaskRecords) > 0
}

// LiveTaskRecords returns the records not yet completed (CompletedAt zero) —
// i.e. still in flight. In-flight consumers (the SessionEnd sweep's "any
// in-flight work?" check) must use this rather than the raw TaskRecords
// slice: since CompleteTaskRecord no longer removes a record, TaskRecords
// mixes live records with already-completed ones awaiting materialization.
func (s *State) LiveTaskRecords() []TaskRecord {
	var live []TaskRecord
	for _, r := range s.TaskRecords {
		if r.CompletedAt.IsZero() {
			live = append(live, r)
		}
	}
	return live
}

// PromptAttribution captures line-level attribution data at the start of each prompt.
// By recording what changed since the last checkpoint BEFORE the agent works,
// we can accurately separate user edits from agent contributions.
type PromptAttribution struct {
	// CheckpointNumber is which checkpoint this was recorded before (1-indexed)
	CheckpointNumber int `json:"checkpoint_number"`

	// UserLinesAdded is lines added by user since the last checkpoint
	UserLinesAdded int `json:"user_lines_added"`

	// UserLinesRemoved is lines removed by user since the last checkpoint
	UserLinesRemoved int `json:"user_lines_removed"`

	// AgentLinesAdded is total agent lines added so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesAdded int `json:"agent_lines_added"`

	// AgentLinesRemoved is total agent lines removed so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesRemoved int `json:"agent_lines_removed"`

	// UserAddedPerFile tracks per-file user additions for accurate modification tracking.
	// This enables distinguishing user self-modifications from agent modifications.
	// See docs/architecture/attribution.md for details.

